import React, { useEffect, useMemo, useState, useRef } from "react";
import { createPortal } from "react-dom";
import { Block } from "./data/block";
import { generateId, generateBlockId } from "./utils/ids";
import { reducer } from "./utils/reducer";
import NotebookBlock from "./components/notebook-block";
import Editor from "./components/editor";
import ParagraphBlock from "./blocks/paragraph";
import BoldTool from "./tools/bold";
import { Button } from "./ui/button";
import { NotebookProvider } from "./context";
import type { NotebookJSProps, BlockRaw } from "./types";

const defaultBlockTypes: any[] = [ParagraphBlock as any];
const defaultTools: any[] = [BoldTool as any];
const defaultMenuItems: any[] = [];
const defaultEditors: any[] = [];

export default function NotebookJS({
  readOnly = false,
  blocks = [],
  onChange = () => {},
  blockTypes = defaultBlockTypes,
  tools = defaultTools,
  editors = defaultEditors,
  menuItems = defaultMenuItems,
  initProps = () => ({}),
  openReference = () => {},
  searchReferences = () => {},
}: NotebookJSProps) {
  const [isEditorOpen, setIsEditorOpen] = useState(false);
  const [editorData, setEditorData] = useState<{
    name: string;
    data: any;
    currentBlockId?: string;
  }>({ name: "", data: {}, currentBlockId: undefined });

  const editorFns = useMemo(
    () => ({
      openEditor: (editor: string, data: unknown, block?: { id: string }) => {
        setEditorData({ name: editor, data, currentBlockId: block?.id });
        setIsEditorOpen(true);
      },
      closeEditor: () => {
        setIsEditorOpen(false);
        setEditorData({ name: "", data: {}, currentBlockId: undefined });
      },
    }),
    [],
  );

  const modifyBlock = (block: BlockRaw) => {
    dispatchNotebookBlocks({ type: "modify-raw-block", block });
  };

  const refsMap = useRef(new Map<string, React.RefObject<any>>());
  const notebookBlocks = blocks.map((b) => new Block(b as any));

  const [focusRequest, setFocusRequest] = useState<{
    id: string;
    where: "start" | "end";
  } | null>(null);
  const dispatchNotebookBlocks = async (action: any) => {
    const currentBlocks = blocks.map((b) => new Block(b as any));
    const result = await reducer({
      state: currentBlocks,
      action,
      refsMap: refsMap.current,
      blocks: blockTypes,
      tools,
      editors,
      menuItems,
      openReference,
      searchReferences,
      initProps,
      addCallback: () => {},
      editorFns,
      dispatcher: dispatchNotebookBlocks,
    });
    const newBlocks = result.map((block: any) => block.toObj());
    onChange(newBlocks);

    if (action.type === "create-new-block") {
      const oldIds = new Set(currentBlocks.map((b: any) => b.id));
      const added = result.find((b: any) => !oldIds.has(b.id));
      if (added) {
        setFocusRequest({ id: added.id, where: "start" });
      }
    }

    if (action.type === "focus-move") {
      const ids = result.map((b: any) => b.id);
      const idx = ids.indexOf(action.id);
      if (idx !== -1) {
        let targetId: string | undefined;
        if (action.dir === "up" && idx > 0) targetId = ids[idx - 1];
        else if (action.dir === "down" && idx < ids.length - 1)
          targetId = ids[idx + 1];
        if (targetId)
          setFocusRequest({
            id: targetId,
            where: action.dir === "up" ? "end" : "start",
          });
      }
    }
  };

  useEffect(() => {
    if (!focusRequest) return;
    const { id, where } = focusRequest;
    const ref = refsMap.current.get(id);
    if (ref?.current) {
      if (where === "start") ref.current.focusAtStart?.();
      else ref.current.focusAtEnd?.();
    }
    setFocusRequest(null);
  }, [focusRequest]);

  useEffect(() => {
    const aliveIds = new Set(blocks.map((b) => (b as any).id));
    for (const key of refsMap.current.keys()) {
      if (!aliveIds.has(key)) refsMap.current.delete(key);
    }
  }, [blocks]);

  const shortcuts = useMemo(() => {
    const blockTypeShortcuts = (blockTypes as any[])
      .filter((blockType) => blockType.shortcut)
      .map((blockType) => ({
        shortcut: blockType.shortcut,
        action: ({ id, blockType: oldBlock, dispatcher }: any) => {
          dispatcher({
            type: "block-type-conversion",
            id,
            oldBlockType: oldBlock.type,
            newBlockType: blockType.type,
          });
        },
      }));
    const menuItemShortcuts = (menuItems as any[])
      .filter((menuItem) => menuItem.shortcut)
      .map((menuItem) => ({
        shortcut: menuItem.shortcut,
        action: ({ id, dispatcher }: any) => {
          dispatcher({
            type: "menu-execution",
            id,
            name: menuItem.name,
            action: menuItem.action,
          });
        },
      }));
    return [...blockTypeShortcuts, ...menuItemShortcuts];
  }, [blockTypes, menuItems]);

  return (
    <>
      <NotebookProvider
        value={{
          blocks: blockTypes as any,
          tools: tools as any,
          editors: editors as any,
          menuItems: menuItems as any,
          dispatcher: dispatchNotebookBlocks,
          editorFns: editorFns as any,
          refsMap: refsMap.current,
        }}
      >
        <div className="notebook-js rounded-md">
          <div className="blocks-container w-full">
            {notebookBlocks.length === 0 ? (
              <div className="flex justify-center items-center py-4">
                <Button
                  variant="outline"
                  className="px-4 py-2 text-sm"
                  onClick={() => {
                    const newBlock = new Block({
                      id: generateId(),
                      blockid: generateBlockId(),
                      type: (blockTypes as any[])[0].type,
                      data: (blockTypes as any[])[0].init(),
                      props: initProps(),
                    } as any);
                    onChange([newBlock.toObj()]);
                  }}
                >
                  Create{" "}
                  {(blockTypes as any[])[0].label ||
                    (blockTypes as any[])[0].name ||
                    "block"}{" "}
                  block
                </Button>
              </div>
            ) : (
              notebookBlocks.map((block) => (
                <NotebookBlock
                  key={block.id}
                  block={block}
                  readOnly={readOnly}
                  shortcuts={shortcuts as any}
                  openReference={openReference as any}
                  searchReferences={searchReferences as any}
                />
              ))
            )}
          </div>
        </div>
      </NotebookProvider>
      {isEditorOpen &&
        createPortal(
          <Editor
            current={editorData.name}
            data={editorData.data}
            currentBlock={notebookBlocks
              .find((b) => b.id === editorData.currentBlockId)
              ?.toObj()}
            close={editorFns.closeEditor}
            modifyBlock={modifyBlock}
          />,
          document.body,
        )}
    </>
  );
}

import type { CSSProperties, ReactElement, ReactNode, RefAttributes, ComponentType } from "react";

export type BlockId = string;
export type BlockTypeId = string;

export type BlockRaw<D = any, P extends Record<string, string> = Record<string, string>> = {
  id: BlockId;
  blockid: string;
  type: BlockTypeId;
  data: D;
  props: P;
};

export interface Shortcut {
  shortcut: string;
  action: (params: {
    id: BlockId;
    blockType?: BlockTypeId | undefined;
    dispatcher: (action: unknown) => void;
  }) => void;
}

export interface MenuItemConfig {
  name: string;
  shortcut?: string;
  action: (
    context: {
      currentBlock: BlockRaw;
      state: BlockRaw[];
      tools: ToolConfig[];
    },
    actions: {
      modifyBlock: (newBlock: BlockRaw) => void;
      focusOnCurrentBlock: () => void;
      openEditor: (name: string, data: unknown) => void;
    },
  ) => void | Promise<unknown>;
}

export interface ToolConfig {
  styles: Array<{ name: string; styles: CSSProperties }>;
  constants: string[];
  label: string;
  icon: ReactNode;
  component?: ComponentType<any>;
  data?: (
    selectedText: string,
    references: { search: (q: string) => unknown; open: (ref: unknown) => unknown },
  ) => unknown;
}

export interface BlockProps<
  D = unknown,
  P extends Record<string, string> = Record<string, string>,
> {
  id: BlockId;
  blockid?: string;
  block?: BlockRaw;
  readOnly: boolean;
  data: D;
  props: P;
  tools: ToolConfig[];
  references: { search: (query: string) => unknown; open: (ref: unknown) => unknown };
  shortcuts: Shortcut[];
  dispatcher: (action: unknown) => void;
  openEditor?: (name: string, data: unknown) => void;
}

export interface BlockComponent<
  D = unknown,
  P extends Record<string, string> = Record<string, string>,
> {
  (props: BlockProps<D, P> & RefAttributes<any>): ReactElement | null;
  label: string;
  icon: ReactNode;
  type: BlockTypeId;
  shortcut?: string;
  init: (prevBlock?: BlockRaw) => D;
  menuItems?: MenuItemConfig[];
  followingBlock?: BlockTypeId;
  onCreateNewBlock?: (
    args: { currentBlock: BlockRaw; state: BlockRaw[] },
    callbacks: { modifyBlock: (b: BlockRaw) => void; focusOnCurrentBlock?: () => void },
  ) => void | Promise<void>;
  onDeleteBlock?: (
    args: { currentBlock: BlockRaw; state: BlockRaw[] },
    callbacks: { modifyBlock: (b: BlockRaw) => void; focusOnCurrentBlock?: () => void },
  ) => void | Promise<void>;
  onBaseTextUpdate?: (
    args: { currentBlock: BlockRaw; state: BlockRaw[] },
    callbacks: { modifyBlock: (b: BlockRaw) => void; focusOnCurrentBlock?: () => void },
  ) => void | Promise<void>;
  onMoveBlock?: (
    args: { currentBlock: BlockRaw; state: BlockRaw[] },
    callbacks: { modifyBlock: (b: BlockRaw) => void; focusOnCurrentBlock?: () => void },
  ) => void | Promise<void>;
  onConvertBlockType?: (
    args: { currentBlock: BlockRaw; state: BlockRaw[]; action?: unknown },
    callbacks: { modifyBlock: (b: BlockRaw) => void; focusOnCurrentBlock?: () => void },
  ) => void | Promise<void>;
  onModifyRawBlock?: (
    args: { currentBlock: BlockRaw; state: BlockRaw[] },
    callbacks: { modifyBlock: (b: BlockRaw) => void; focusOnCurrentBlock?: () => void },
  ) => void | Promise<void>;
  onMenuItem?: (
    args: { action: { name: string; shortcut?: string }; currentBlock: BlockRaw; state: BlockRaw[] },
    callbacks: { modifyBlock: (b: BlockRaw) => void; focusOnCurrentBlock?: () => void },
  ) => void | Promise<void>;
}

export interface EditorProps<D = unknown> {
  data: D;
  currentBlock: BlockRaw;
  modifyBlock: (block: BlockRaw) => void;
  close: () => void;
}

export interface EditorComponent<D = unknown> {
  (props: EditorProps<D>): ReactElement | null;
  label: string;
}

export interface NotebookJSProps {
  readOnly?: boolean;
  blocks?: BlockRaw[]; // Controlled blocks data
  onChange?: (blocks: BlockRaw[]) => void; // Fired on block change
  blockTypes?: BlockComponent[]; // List of available block types
  tools?: ToolConfig[];
  editors?: EditorComponent[];
  menuItems?: MenuItemConfig[];
  initProps?: () => Record<string, string>;
  openReference?: (...args: any[]) => any;
  searchReferences?: (...args: any[]) => any;
}

// Block data shapes
export interface ParagraphBlockData { text: string; inlineStyles: any[] }
export interface HeadingBlockData { text: string; inlineStyles: any[] }
export interface SubheadingBlockData { text: string; inlineStyles: any[] }
export interface OrderedListBlockData { text: string; inlineStyles: any[]; indentation: number; numbering: number[]; manual: boolean }
export interface UnorderedListBlockData { text: string; inlineStyles: any[]; indentation: number }
export interface ImageBlockData { text: string; inlineStyles: any[]; img: string }
export interface LatexVariable { name: string; description: string }
export interface LatexBlockData { text: string; inlineStyles: any[]; latex: string; variables: LatexVariable[] }
export interface CanvasBlockData { text: string; inlineStyles: any[]; elements: any[] | null; files: Record<string, any> }
export interface TableCellData {
  content: string; inlineStyles: any[]; hidden: boolean; rowspan: number; colspan: number; isHeader: boolean; groupId: string; borders: boolean
}
export interface TableBlockData { text: string; inlineStyles: any[]; rows: TableCellData[][] }

// Editor data shapes
export interface PropertiesEditorData {}
export interface SetNumberingEditorData {}
export interface ImageEditorData { handleSelectImg: () => void }
export interface CanvasEditorData {}
export interface TableEditorData { tools: ToolConfig[]; calculateBorders?: (...args: any[]) => string }
export interface LatexEditorData {}

import React, { createContext, useContext } from "react";

type NotebookCtx = {
  blocks: any[];
  tools: any[];
  editors: any[];
  menuItems: any[];
  dispatcher: (action: any) => void;
  editorFns: any;
  refsMap: Map<string, React.RefObject<any>>;
};

const Ctx = createContext<NotebookCtx | null>(null);

export function NotebookProvider({ value, children }: { value: NotebookCtx; children: React.ReactNode }) {
  return <Ctx.Provider value={value}>{children}</Ctx.Provider>;
}

export function useNotebook() {
  const ctx = useContext(Ctx);
  if (!ctx) throw new Error("useNotebook must be used within NotebookProvider");
  return ctx;
}

import { GENIDREGEXP, BLOCKIDREGEXP, PROPKEY } from "./const";
import { List, Wrap } from "../utils/errors";
import type { BlockRaw } from "../types";

export type BlockInit<D = unknown, P extends Record<string, string> = Record<string, string>> = {
  id: string;
  blockid: string;
  type: string;
  data: D;
  props: P;
};

export class Block<D = unknown, P extends Record<string, string> = Record<string, string>> {
  #id: string;
  #blockid: string;
  #type: string;
  #data: D;
  #props: P;

  constructor({ id = "", blockid = "", type = "", data = {} as D, props = {} as P }: Partial<BlockInit<D, P>> & BlockInit<D, P>) {
    const idError = Block.checkId(id);
    if (idError === true) this.#id = id; else throw Wrap("Invalid Block", idError);
    const blockidError = Block.checkBlockid(blockid);
    if (blockidError === true) this.#blockid = blockid; else throw Wrap("Invalid Block", blockidError);
    const typeError = Block.checkType(type);
    if (typeError === true) this.#type = type; else throw Wrap("Invalid Block", typeError);
    const dataError = Block.checkData(data as unknown);
    if (dataError === true) this.#data = data as D; else throw Wrap("Invalid Block", dataError);
    const propsError = Block.checkProps(props as unknown);
    if (propsError === true) this.#props = props as P; else throw Wrap("Invalid Props", propsError);
  }

  get id() { return this.#id; }
  get blockid() { return this.#blockid; }
  get type() { return this.#type; }
  get data(): D { return this.#data; }
  get props(): P { return this.#props; }

  set id(value: string) {
    const error = Block.checkId(value);
    if (error === true) this.#id = value; else throw Wrap("Cannot set id", error);
  }
  set blockid(value: string) {
    const error = Block.checkBlockid(value);
    if (error === true) this.#blockid = value; else throw Wrap("Cannot set blockid", error);
  }
  set type(value: string) {
    const error = Block.checkType(value);
    if (error === true) this.#type = value; else throw Wrap("Cannot set type", error);
  }
  set data(value: D) {
    const error = Block.checkData(value);
    if (error === true) this.#data = value as D; else throw Wrap("Cannot set data", error);
  }
  set props(value: P) {
    const error = Block.checkProps(value);
    if (error === true) this.#props = value as P; else throw Wrap("Cannot set props", error);
  }

  toObj(): BlockRaw<D, P> {
    return { id: this.#id, blockid: this.#blockid, type: this.#type, data: this.#data, props: this.#props } as BlockRaw<D, P>;
  }

  static checkId(value: unknown): true | Error {
    try {
      if (typeof value !== "string") throw new Error("id must be string");
      if (!GENIDREGEXP.test(value)) throw new Error("id must match GENIDREGEXP");
    } catch (e: any) { return Wrap("Invalid id", e); }
    return true;
  }
  static checkBlockid(value: unknown): true | Error {
    try {
      if (typeof value !== "string") throw new Error("blockid must be string");
      if (!BLOCKIDREGEXP.test(value)) throw new Error("blockid must match BLOCKIDREGEXP");
    } catch (e: any) { return Wrap("Invalid blockid", e); }
    return true;
  }
  static checkType(value: unknown): true | Error {
    try {
      if (typeof value !== "string") throw new Error("type must be string");
    } catch (e: any) { return Wrap("Invalid type", e); }
    return true;
  }
  static checkData(value: unknown): true | Error {
    try {
      if (value === undefined || value === null) throw new Error("data must exist");
    } catch (e: any) { return Wrap("Invalid data", e); }
    return true;
  }
  static checkProps(value: unknown): true | Error {
    try {
      if (typeof value !== "object" || value === null) throw new Error("props must be object");
      const obj = value as Record<string, unknown>;
      const keys = Object.keys(obj);
      const keysErrors: Error[] = [];
      for (let i = 0; i < keys.length; i++) {
        const key = keys[i];
        const error = Block.checkPropsKey(key);
        if (error !== true) keysErrors.push(error);
      }
      const vals = Object.values(obj);
      const valsErrors: Error[] = [];
      for (let i = 0; i < vals.length; i++) {
        const val = vals[i];
        const error = Block.checkPropsVal(val);
        if (error !== true) valsErrors.push(error);
      }
      const allErrors = ([] as Error[]).concat(keysErrors, valsErrors);
      if (allErrors.length > 0) throw List(allErrors);
    } catch (e: any) { return Wrap("Invalid props", e); }
    return true;
  }
  static checkPropsKey(value: unknown): true | Error {
    try {
      if (typeof value !== "string") throw new Error("props key must be string");
      if (!PROPKEY.test(value)) throw new Error("props key must match PROPKEY");
    } catch (e: any) { return Wrap("Invalid props key", e); }
    return true;
  }
  static checkPropsVal(value: unknown): true | Error {
    try {
      if (typeof value !== "string") throw new Error("props value must be string");
    } catch (e: any) { return Wrap("Invalid props val", e); }
    return true;
  }
}

export const GENIDREGEXP = /^[0-9a-fA-F]{24}$/;
export const BLOCKIDREGEXP = /^[0-9a-fA-F_]{10}$/;
export const PROPKEY = /^[a-z_]{1,16}$/;
export const KC_DELETE_BLOCK = "block-delete" as const;
export const KC_MOVE_BLOCK_UP = "block-move-up" as const;
export const KC_MOVE_BLOCK_DOWN = "block-move-down" as const;
export const KC_SHIFT_FOCUS_UP = "focus-shift-up" as const;
export const KC_SHIFT_FOCUS_DOWN = "focus-shift-down" as const;
export const KC_CONVERT_BLOCK_TYPE = "convert-block-type" as const;
export const KC_MENU_ACTION = "menu-action" as const;
export const KC_TOOL_TOGGLE = "tool-toggle" as const;
export const KC_CUSTOM_SHORTCUT = "custom-shortcut" as const;

import type { BlockRaw, BlockComponent, ToolConfig, MenuItemConfig, EditorComponent } from "../types";

export type BlockMoveDirection = "up" | "down";
export type FocusMoveDirection = "up" | "down";

export type Action =
  | { type: "block-type-conversion"; id: string; oldBlockType: string; newBlockType: string }
  | { type: "menu-execution"; id: string; name: string; action: Function }
  | { type: "base-text-update"; id: string; text: string; inlineStyles: any[] }
  | { type: "block-delete"; id: string }
  | { type: "block-move"; id: string; dir: BlockMoveDirection }
  | { type: "focus-move"; id: string; dir: FocusMoveDirection }
  | { type: "create-new-block"; id?: string; position: "before" | "after"; blockType: string }
  | { type: "modify-raw-block"; block: BlockRaw };

export type Callback = (ctx: { refsMap: Map<string, React.RefObject<any>> }) => void;

export type ReducerEnv = {
  state: import("../data/block").Block[];
  action: Action;
  refsMap: Map<string, React.RefObject<any>>;
  blocks: BlockComponent[];
  tools: ToolConfig[];
  editors: EditorComponent[];
  menuItems: MenuItemConfig[];
  openReference?: Function;
  searchReferences?: Function;
  initProps: () => Record<string, string>;
  addCallback: (cb: Callback) => void;
  editorFns: any;
  dispatcher: (action: Action) => void;
};

import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

// Function to convert Draft.js inline styles to our application format
export function convertFromDraftToInlineStyles(rawInlineStyles: Array<{ offset: number; length: number; style: string }>) {
  return rawInlineStyles.map((style) => ({
    offset: style.offset,
    length: style.length,
    style: style.style,
  }));
}

// Helper function to get the current selection bounds
export function getSelectionBounds(): {
  top: number; left: number; width: number; height: number; bottom: number;
} | null {
  const selection = window.getSelection();
  if (!selection || selection.rangeCount === 0) return null;
  const range = selection.getRangeAt(0);
  const bounds = range.getBoundingClientRect();
  if (bounds.width === 0 && bounds.height === 0) return null;
  return { top: bounds.top, left: bounds.left, width: bounds.width, height: bounds.height, bottom: bounds.bottom };
}

export function isCmdOS(): boolean {
  return navigator.platform === "MacIntel";
}

export function deepEquals(...items: any[]): boolean {
  const equal = (a: any, b: any): boolean => {
    if (a === b) return true;
    if (a && b && typeof a === "object" && typeof b === "object") {
      if ((a as any).constructor !== (b as any).constructor) return false;
      let length: number, i: any, keys: string[];
      if (Array.isArray(a)) {
        length = a.length;
        if (length !== b.length) return false;
        for (i = length; i-- !== 0;) if (!equal(a[i], b[i])) return false;
        return true;
      }
      if (a instanceof Map && b instanceof Map) {
        if (a.size !== b.size) return false;
        for (i of a.entries()) if (!b.has(i[0])) return false;
        for (i of a.entries()) if (!equal(i[1], b.get(i[0]))) return false;
        return true;
      }
      if (a instanceof Set && b instanceof Set) {
        if (a.size !== b.size) return false;
        for (i of a.entries()) if (!b.has(i[0])) return false;
        return true;
      }
      if (ArrayBuffer.isView(a) && ArrayBuffer.isView(b)) {
        length = (a as any).length;
        if (length !== (b as any).length) return false;
        for (i = length; i-- !== 0;) if ((a as any)[i] !== (b as any)[i]) return false;
        return true;
      }
      if ((a as any).constructor === RegExp) return a.source === b.source && a.flags === b.flags;
      if ((a as any).valueOf !== Object.prototype.valueOf) return (a as any).valueOf() === (b as any).valueOf();
      if ((a as any).toString !== Object.prototype.toString) return (a as any).toString() === (b as any).toString();
      keys = Object.keys(a);
      length = keys.length;
      if (length !== Object.keys(b).length) return false;
      for (i = length; i-- !== 0;) if (!Object.prototype.hasOwnProperty.call(b, keys[i])) return false;
      for (i = length; i-- !== 0;) {
        const key = keys[i];
        if (key === "_owner" && (a as any).$$typeof) continue;
        if (!equal(a[key], (b as any)[key])) return false;
      }
      return true;
    }
    return a !== a && b !== b;
  };
  if (items.length === 0) return false;
  const first = items[0];
  for (let i = 1; i < items.length; i++) if (!equal(first, items[i])) return false;
  return true;
}

export function Wrap(message: string, error: Error): Error {
  const e = new Error(`${message}:${error.message}`);
  (e as any).stack = error.stack;
  return e;
}

export function List(errors: Error[]): Error {
  const e = new Error(`[${errors.map((oe) => oe.message).join(",")}]`);
  return e;
}

export function Unwrap(wrappedError: Error): Error[] {
  const message = wrappedError.message
    .split(":")
    .map((a) => a.trim())
    .reverse();
  const stack = (wrappedError.stack || "").split("\n");
  stack.shift();
  const errs: Error[] = [];
  const len = message.length;
  for (let i = 0; i < len; i++) {
    const err = new Error(message[i]);
    (err as any).stack = [`Error: ${message[i]}`, ...stack].join("\n");
    stack.shift();
    errs.push(err);
  }
  return errs;
}

export function Has(wrappedError: Error, errorMessage: string): boolean {
  const errors = Unwrap(wrappedError);
  const len = errors.length;
  for (let i = 0; i < len; i++) {
    const err = errors[i];
    if (err.message === errorMessage) {
      return true;
    }
  }
  return false;
}

export function Panic(location: string, panicError: Error, handledError: Error): void {
  const e = new Error(
    `Error recovering at ${location} from error: ${handledError.message}. ERROR THROWN: ${panicError.message}`,
  );
  (e as any).stack = (panicError as any).stack;
  // eslint-disable-next-line no-console
  console.error(e);
}

export function generateId(): string {
  const bytes = new Uint8Array(12); // 12 bytes = 24 hex chars
  crypto.getRandomValues(bytes);
  return Array.from(bytes, (b) => b.toString(16).padStart(2, "0")).join("");
}

export function generateBlockId(): string {
  const chars = "0123456789abcdefABCDEF_";
  const bytes = new Uint8Array(10);
  crypto.getRandomValues(bytes);
  return Array.from(bytes, (b) => chars[b % chars.length]).join("");
}

